import {initializeKnowledge} from './knowledge.js';
import {mountKnowledge} from './knowledge-ui.js';
const knowledgeSeed=await fetch('./knowledge-seed.json').then(r=>{if(!r.ok)throw Error('Knowledge base could not load');return r.json();});
import * as C from './core.js';
let state,selected,view='Today',query='',filter='All';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{state=JSON.parse(localStorage.getItem('dealerdesk-demo-v1'))||C.seed();}catch{state=C.seed();}selected=state.leads[0]?.id;
const pages=['Today','Conversations','Customers','Appointments','Inventory','Knowledge Base','Reports','Connections'];
function save(){localStorage.setItem('dealerdesk-demo-v1',JSON.stringify(state));render();}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function fmt(at){return new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:state.settings.timezone}).format(at);}
function vehicle(l){const v=state.inventory.find(v=>v.id===l.vehicleId);return v?`${v.year} ${v.make} ${v.model}`:'Vehicle to confirm';}
function badge(l){return `<span class="badge ${l.optOut?'red':l.takeover?'warn':''}">${l.optOut?'Opted out':l.takeover?'Human takeover':'Assistant active'}</span>`;}
function row(l,reason=''){return `<div class="row"><div class="avatar">${esc(l.name.split(' ').map(n=>n[0]).join(''))}</div><div class="grow"><strong>${esc(l.name)}</strong><div class="muted">${esc(reason||vehicle(l))}</div></div>${badge(l)}<button class="link" data-open="${l.id}" aria-label="Open ${esc(l.name)}">↗</button></div>`;}
function stats(){const a=state.alerts.filter(a=>!a.resolved),ap=state.leads.flatMap(l=>l.appointments).filter(a=>a.status==='booked');return `<div class="stats">${[['Active leads',state.leads.filter(l=>!['Sold','Lost'].includes(l.stage)).length,'Across all lead sources'],['Needs attention',a.length,'Only meaningful escalations'],['Booked visits',ap.length,'Upcoming appointments'],['Vehicles sold',state.leads.filter(l=>l.stage==='Sold').length,'Attributed to original source']].map(x=>`<div class="stat"><small>${x[0]}</small><strong>${x[1]}</strong><em>${x[2]}</em></div>`).join('')}</div>`;}
function today(){return stats()+`<div class="grid"><div class="panel"><h2>Your next best actions</h2><div class="sub">Manager decisions, missing facts, and customers waiting for you.</div>${state.alerts.filter(a=>!a.resolved).map(a=>{const l=C.lead(state,a.leadId);return row(l,a.reason)+`<button class="link" data-resolve="${a.id}">Mark handled</button>`;}).join('')||'<div class="empty">You are all caught up.</div>'}</div><div><div class="panel"><h2>Upcoming visits</h2><div class="sub">${esc(state.settings.timezone)}</div>${appointments(true)}</div><div class="panel"><h2>Quietly working for you</h2><p class="muted">Follow-ups run at 24 hours, 3 days, and 7 days. Replies reset the sequence. Opt-outs, purchases, and takeover stop it.</p><div class="actions"><button data-tick="1">Simulate +24 hours</button></div><div class="muted">${state.jobs.filter(j=>j.status==='pending').length} scheduled actions · all simulated</div></div></div></div><div class="panel"><h2>Recent conversations</h2>${state.leads.slice(-4).reverse().map(l=>row(l,l.summary)).join('')}</div>`;}
function conversations(){let ls=state.leads.filter(l=>(l.name+' '+l.phone+' '+vehicle(l)).toLowerCase().includes(query.toLowerCase())&&(filter==='All'||l.stage===filter));let l=state.leads.find(l=>l.id===selected)||ls[0];return `<div class="toolbar"><input class="search" id="search" placeholder="Search customers, vehicles, phone…" value="${esc(query)}"><select id="filter">${['All',...C.stages].map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select></div><div class="workspace"><div class="panel lead-list">${ls.map(x=>`<div class="row ${l?.id===x.id?'selected':''}" data-select="${x.id}" tabindex="0"><div class="avatar">${esc(x.name[0])}</div><div class="grow"><strong>${esc(x.name)}</strong><div class="muted">${esc(x.source)} · ${esc(x.stage)}</div></div></div>`).join('')||'<div class="empty">No customers match.</div>'}</div><div>${l?detail(l):'<div class="panel empty">Add a lead to begin.</div>'}</div></div>`;}
function detail(l){return `<div class="panel"><div class="row" style="border:0;padding-top:0"><div class="grow"><h2>${esc(l.name)}</h2><div class="muted">${esc(l.phone||'No phone shared')} · ${esc(l.source)}</div></div>${badge(l)}</div><div class="detail-meta"><span class="badge">${esc(vehicle(l))}</span><select id="stage">${C.stages.map(s=>`<option ${s===l.stage?'selected':''}>${s}</option>`).join('')}</select></div><p class="muted">Latest customer message: ${esc(l.summary)}</p><div class="actions"><button id="takeover">${l.takeover?'Resume assistant':'Take over conversation'}</button><button id="book">Book / reschedule visit</button></div><div class="conversation">${l.messages.map(m=>`<div class="bubble ${m.direction==='out'?'out':''}">${esc(m.body)}<small>${m.direction==='out'?'Dealership':'Customer'} · ${esc(m.status)} · ${fmt(m.at)}</small></div>`).join('')}</div><label>Test a customer reply<textarea id="reply" placeholder="Try: Is it available? / guarantee financing / STOP"></textarea></label><div class="actions"><button class="primary" id="simulate">Simulate incoming text</button><button id="human">Send as human (simulated)</button></div><div class="muted">Human send immediately pauses the assistant. No external SMS is sent.</div></div><div class="panel"><h2>Customer record</h2><div class="muted">SMS consent: ${l.optOut?'Withdrawn':l.consent?esc(l.consent.evidence):'Not recorded — texting blocked'}</div><div class="muted">Lead sources: ${esc(l.sources.join(', '))}</div>${l.notes.map(n=>`<div class="row"><div>${esc(n.body)}<div class="muted">${fmt(n.at)}</div></div></div>`).join('')}<label>Internal note<textarea id="note"></textarea></label><button id="savenote">Save note</button></div>`;}
function appointments(compact=false){const rows=state.leads.flatMap(l=>l.appointments.map(a=>({l,a}))).sort((x,y)=>x.a.start-y.a.start);return rows.map(({l,a})=>`<div class="row"><div class="grow"><strong>${esc(l.name)}</strong><div class="muted">${fmt(a.start)} · ${esc(a.status)}</div></div>${compact?`<button class="link" data-open="${l.id}">Open ↗</button>`:`<button data-ap="${l.id}|${a.id}|visited">Visited</button><button data-ap="${l.id}|${a.id}|missed">Missed</button><button data-ap="${l.id}|${a.id}|cancelled">Cancel</button>`}</div>`).join('')||'<div class="empty">No visits booked yet. Open a customer to schedule one.</div>';}
function inventory(){return `<div class="banner">SAMPLE INVENTORY · These are fictional listings, not dealership facts.</div><div class="inventory">${state.inventory.map(v=>`<div class="panel"><div class="car-graphic" aria-hidden="true">${v.make==='Ford'?'▰':'▱'}</div><span class="badge ${v.status==='sold'?'warn':''}">${esc(v.status)}</span><h2>${v.year} ${esc(v.make)} ${esc(v.model)}</h2><div class="muted">Stock ${esc(v.id)} · ${v.mileage.toLocaleString()} miles</div><div class="amount">$${v.price.toLocaleString()}</div><div class="muted">Verified ${fmt(v.verifiedAt)}</div></div>`).join('')}</div><div class="panel"><h2>Verified inventory feed</h2><p class="muted">The server supports an authenticated inventory import. Records older than 24 hours require verification before quoting. A sold vehicle is never offered as available.</p></div>`;}
function reports(){return stats()+`<div class="panel"><h2>Performance by lead source</h2><div class="sub">All-time · original-source attribution · unique customers with appointments (including cancelled), visits and sales</div><div class="report-row head"><span>SOURCE</span><span>LEADS</span><span>BOOKED</span><span>VISITED</span><span>SOLD</span></div>${C.report(state).map(r=>`<div class="report-row"><span>${r.source}<div class="bar"><i style="width:${Math.min(r.leads*25,100)}%"></i></div></span><strong>${r.leads}</strong><span>${r.appointments}</span><span>${r.visits}</span><span>${r.sales}</span></div>`).join('')}<button id="export">Export demo data</button></div>`;}
function connections(){return `<div class="panel"><h2>Launch connections</h2><div class="sub">Prepared does not mean connected. Account access has not been verified.</div>${[['Business SMS','Twilio adapter prepared; owner account, number and A2P approval required.'],['Facebook lead forms','Lead retrieval permission, Page/business access, webhook and test lead required.'],['Facebook Page messages','Separate Page messaging approval and messaging-window enforcement required.'],['Personal Marketplace','Unsupported automation. Manually enter customer-shared contacts and record consent.'],['CarGurus','Dealer must confirm supported ADF/XML or delivery access and send a test lead.'],['AutoTrader','Dealer must separately confirm supported delivery and send a test lead.'],['Inventory','Verified dealer feed and update process required.'],['AI assistant','Rule-based simulator active. AI API adapter prepared but not connected or evaluated live.'],['Live hosting & backups','Server package prepared; owner hosting and off-site backup account required.']].map(([n,t])=>`<div class="integration"><div><strong>${n}</strong><p class="muted">${t}</p></div><span class="badge warn">${n==='Personal Marketplace'?'Unsupported':'Not connected'}</span></div>`).join('')}</div><div class="panel"><h2>Review tools</h2><p class="muted">Reset fictional data or export this device's review state. Never enter real customer information into this browser-only demo.</p><button id="reset">Reset simulated data</button></div>`;}
function render(){ $('#today').textContent=new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(Date.now());$('#nav').innerHTML=pages.map((p,i)=>`<button class="${p===view?'active':''}" data-nav="${p}">${['◈','◌','▤','▦','▱','◇','▥','⚙'][i]} &nbsp; ${p}</button>`).join('');$('#title').textContent=view==='Today'?'Your day, in focus.':view;$('#subtitle').textContent=view==='Today'?'Every conversation. A clear next step.':'A dealership workspace built around the next conversation.';$('#content').innerHTML=view==='Today'?today():['Conversations','Customers'].includes(view)?conversations():view==='Appointments'?`<div class="panel"><h2>Visits & test drives</h2><div class="sub">30-minute slots · ${esc(state.settings.timezone)} · open ${state.settings.hours.start}:00–${state.settings.hours.end}:00</div>${appointments()}</div>`:view==='Inventory'?inventory():view==='Knowledge Base'?'<div id="knowledge-root"></div>':view==='Reports'?reports():connections();if(view==='Knowledge Base'){initializeKnowledge(state,knowledgeSeed);mountKnowledge($('#knowledge-root'),{entries:state.knowledge,onSave:async(input,updated)=>{state.knowledge=updated;localStorage.setItem('dealerdesk-demo-v1',JSON.stringify(state));return updated;}});}}
function run(fn){try{fn();save();}catch(e){toast(e.message);}}
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-select]');if(!t)return;const d=t.dataset;if(d.nav){view=d.nav;render();}if(d.open){selected=d.open;view='Conversations';render();}if(d.select){selected=d.select;render();}if(d.resolve)run(()=>state.alerts.find(a=>a.id===d.resolve).resolved=true);if(d.tick)run(()=>{C.tick(state,state.clock+86400000);toast('Demo clock advanced 24 hours');});if(d.ap)run(()=>C.appointmentStatus(state,...d.ap.split('|')));
 if(t.id==='add')$('#modal').showModal();if(t.id==='close')$('#modal').close();if(t.id==='takeover')run(()=>C.takeover(state,selected,!C.lead(state,selected).takeover));if(t.id==='simulate')run(()=>{const text=$('#reply').value.trim();if(!text)throw Error('Enter a customer reply');C.inbound(state,selected,text,crypto.randomUUID(),Math.max(Date.now(),state.clock));});if(t.id==='human')run(()=>{const l=C.lead(state,selected),text=$('#reply').value.trim();if(!text)throw Error('Enter a message');if(l.optOut||!l.consent)throw Error('Text blocked: no active SMS consent');C.takeover(state,selected);C.message(state,l,text);});
 if(t.id==='book'){const start=prompt('Visit time with timezone offset, e.g. 2026-10-28T14:00:00-07:00');if(start)run(()=>C.book(state,selected,start,Math.max(Date.now(),state.clock)));}if(t.id==='savenote')run(()=>{const body=$('#note').value.trim();if(body)C.lead(state,selected).notes.push({body,at:state.clock});});if(t.id==='reset'&&confirm('Reset all simulated data on this device?')){state=C.seed();selected=state.leads[0].id;save();}if(t.id==='export'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='dealerdesk-demo-export.json';a.click();URL.revokeObjectURL(a.href);}});
document.addEventListener('change',e=>{if(e.target.id==='stage')run(()=>C.setStage(state,selected,e.target.value));if(e.target.id==='filter'){filter=e.target.value;render();}});document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
$('#source').innerHTML=C.sources.map(s=>`<option>${s}</option>`).join('');$('#vehicle').innerHTML='<option value="">To confirm</option>'+state.inventory.map(v=>`<option value="${v.id}">${esc(v.make)} ${esc(v.model)}</option>`).join('');$('#leadform').addEventListener('submit',e=>{e.preventDefault();run(()=>{const f=new FormData(e.target);const l=C.ingest(state,{...Object.fromEntries(f),externalId:crypto.randomUUID(),consent:f.get('consent')?{granted:true,at:Date.now(),evidence:'Simulated manual opt-in'}:null});selected=l.id;view='Conversations';$('#modal').close();e.target.reset();});});render();
